@startuml

class Patient {
  + Name
}

class Family {
  + Name
}

class Appointment {
  + Date
  + Time
}

class Visit {
  + Diagnosis
  + Treatment
}

class Medication {
  + Name
}

class Doctor {
  + Name
}

class Receptionist {}

class Nurse {}

class DoctorOfficeSystem {}

Patient "0..*" -- "1" Family : belongs to
Family "1" -- "0..1" Doctor : hasPrimaryCare
Patient "1" -- "0..*" Appointment : scheduled for
Patient "1" -- "0..*" Visit : undergoes
Visit "1" -- "0..*" Medication : prescribes
Visit "0..*" -- "1" Doctor : performed by
Visit "0..*" -- "1" Nurse : recorded by
Appointment "0..*" -- "1" Receptionist : scheduled by
Visit "0..*" -- "1" Doctor : viewed by
Visit "0..*" -- "1" Nurse : viewed by
Visit "0..*" -- "1" Doctor : viewed by
Patient "0..*" -- "1" Receptionist : information entered by
DoctorOfficeSystem ..> Patient : manages
DoctorOfficeSystem ..> Appointment : manages
DoctorOfficeSystem ..> Visit : manages

@enduml

